import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root group for scene placement
  const root = new Group();
  root.position.set(0, 3, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Backdrop plane for the stage (7x6 units at z=-2.5)
  const backdropGeom = new PlaneGeometry(7, 6);

  // Create gradient material with engineered colors
  const gradientMat = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    side: ctx.THREE.DoubleSide,
  });

  // Define gradient stops from ink to surface
  const inkColor = new Color('#16161d');
  const surfaceColor = new Color('#0b0b10');

  // TSL-based gradient: lerp from ink (top) to surface (bottom) using normalized UV.y
  const normalizedY = uv().y;
  const gradientColor = vec3(
    normalizedY.mix(inkColor.r, surfaceColor.r),
    normalizedY.mix(inkColor.g, surfaceColor.g),
    normalizedY.mix(inkColor.b, surfaceColor.b)
  );

  gradientMat.colorNode = gradientColor;

  const backdrop = new Mesh(backdropGeom, gradientMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // Load and apply the image texture to a plane
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';

  const textureGeom = new PlaneGeometry(4, 2.5);
  const textureMat = new MeshBasicNodeMaterial({
    color: new Color('#ffffff'),
    transparent: true,
  });

  const textureQuad = new Mesh(textureGeom, textureMat);
  textureQuad.position.z = 0.1;
  root.add(textureQuad);

  // Load texture asynchronously and apply
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    textureMat.colorNode = tex;
    textureMat.needsUpdate = true;
  });

  // Create the headline text: "Pricing"
  const headlineText = ctx.fontAtlas.createText('Pricing', {
    fontSize: 96,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2,
  });

  headlineText.position.set(0, 1.5, 0.2);
  root.add(headlineText);

  // Cleanup function
  root.userData.cleanup = function() {
    // Dispose geometries
    backdropGeom.dispose();
    textureGeom.dispose();

    // Dispose materials
    gradientMat.dispose();
    textureMat.dispose();

    // Text cleanup handled by fontAtlas
  };

  return root;
}
